refentry.refsect1:
&reftitle.description;
public Yaf_Controller_Abstract::__construct
Yaf_Controller_Abstract::__construct est appelée par Yaf lorsqu'un objet contrôleur est créé pendant la distribution. Elle ne prend aucun argument et ne devrait pas être appelée directement. Comme elle n'est pas destinée à être surchargée avec une logique personnalisée, la méthode Yaf_Controller_Abstract::init est fournie à la place comme point d'entrée d'initialisation côté utilisateur.

  &reftitle.examples;

   Exemple avec Yaf_Controller_Abstract::__construct


<?php
class IndexController extends Yaf_Controller_Abstract
{
    // __construct() est appelée par Yaf_Dispatcher lorsque le contrôleur
    // est instancié pendant la distribution ; elle ne devrait être ni
    // appelée manuellement, ni surchargée. Définir init() à la place :

    public function init() {
        // au moment où init() s'exécute, le distributeur a déjà câblé
        // le contrôleur : la requête, la réponse et le moteur de vue
        // sont tous disponibles
        var_dump($this->getRequest() instanceof Yaf_Request_Abstract);
        var_dump($this->getResponse() instanceof Yaf_Response_Abstract);
        var_dump($this->getView() instanceof Yaf_View_Interface);
    }

    public function indexAction() {
        // ...
    }
}
?>


